%[text] %[text:anchor:H_F187FA31] #### dxfList2Import
dxfList2Import=defDXFList2Import(dxfFiles, 1,2)
dxfList2Import.dxfPath{1}=NewtestStatorDXFPath  ;
dxfList2Import.dxfPath{2}=NewtestRotorDXFPath  ;

